//! Repository for SupplierPrice entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written supplier-price SQL (4-layer rule: services orchestrate, repos hold
//! SQL).
//!
//! PXB-1 correction, load-bearing here: `buying.supplier_prices` has NO CRUD route and NO generic
//! write path. Its ONLY writers are the blanket-agreement verbs — confirm mints one row per
//! agreement line, the open-price update propagates, and close/cancel unlinks (soft-deletes) the
//! agreement's rows. That is what makes a supplier price auditable to the agreement that produced
//! it.
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<SupplierPrice, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::PgPool;
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::SupplierPrice;

/// Table name for SupplierPrice entities
pub const TABLE_NAME: &str = "buying.supplier_prices";

/// Repository for SupplierPrice entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct SupplierPriceRepository(
    backbone_orm::GenericCrudRepository<SupplierPrice, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for SupplierPriceRepository {
    type Target = backbone_orm::GenericCrudRepository<SupplierPrice, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl SupplierPriceRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// Hand-written SupplierPrice SQL. Every method takes the caller's connection so the price write
/// commits atomically with the agreement verb that caused it — there is no standalone price write.
impl SupplierPriceRepository {
    /// Mint (or refresh) the supplier-price row for one agreement line. Used by the agreement
    /// confirm (one row per line, from the negotiated rate) and by the open-price update (same
    /// upsert, new rate). One row per (company, supplier, item, agreement line) — re-confirming
    /// cannot mint duplicates.
    #[allow(clippy::too_many_arguments)]
    pub async fn upsert_for_agreement_line(
        &self,
        conn: &mut sqlx::PgConnection,
        company_id: Uuid,
        supplier_id: Uuid,
        item_id: Uuid,
        price: Decimal,
        currency: &str,
        agreement_id: Uuid,
        agreement_line_id: Uuid,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO buying.supplier_prices
                (id, company_id, supplier_id, item_id, price, currency, agreement_id, agreement_line_id)
               VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
               ON CONFLICT (company_id, supplier_id, item_id, agreement_line_id)
               WHERE (metadata->>'deleted_at') IS NULL DO UPDATE SET
                   price = EXCLUDED.price,
                   currency = EXCLUDED.currency"#,
        )
        .bind(Uuid::new_v4()).bind(company_id).bind(supplier_id).bind(item_id)
        .bind(price).bind(currency).bind(agreement_id).bind(agreement_line_id)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Unlink an agreement's price rows (soft-delete) when the agreement closes or is cancelled —
    /// a closed blanket no longer prices new call-offs. Takes the caller's connection so the
    /// unlink commits with the status flip.
    pub async fn soft_delete_for_agreement(
        &self,
        conn: &mut sqlx::PgConnection,
        agreement_id: Uuid,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"UPDATE buying.supplier_prices
                  SET metadata = jsonb_set(metadata, '{deleted_at}', to_jsonb(NOW()))
                WHERE agreement_id=$1 AND (metadata->>'deleted_at') IS NULL"#,
        )
        .bind(agreement_id)
        .execute(conn)
        .await?;
        Ok(())
    }
}

backbone_core::impl_crud_repository!(SupplierPriceRepository, SupplierPrice, soft_delete);
